begin;
create temporary table kk_art_changed(id uuid primary key) on commit drop;
with changed as (
 insert into public.kk_museums as m(id,inventory_key,name,city,province,street_address,postal_code,country,website_url,latitude,longitude,summary,operating_status,publication_status,verification_status,tags,photos,is_art_museum)
 select id,inventory_key,name,city,province,street_address,postal_code,country,website_url,latitude,longitude,summary,operating_status,publication_status,verification_status,tags,photos,is_art_museum from jsonb_populate_recordset(null::public.kk_museums,'[{"id":"ffe7c7e6-0c5e-59c1-a15f-30cbab35178c","inventory_key":"museum-nl:noord-veluws-museum","name":"Noord-Veluws Museum Nunspeet","city":"Nunspeet","province":"Gelderland","street_address":"Winckelweg 17a","postal_code":"8071 DN","country":"NL","website_url":"https://www.noord-veluws-museum.nl/","latitude":52.374258,"longitude":5.780726,"summary":"Ontdek waarom kunstenaars zich op de Noord-Veluwe thuis voelden. Schilderijen tonen bos, heide en het leven dichtbij de natuur. Het museum geeft een podium aan de kunstenaars die dit landschap vanaf de late negentiende eeuw vastlegden.","operating_status":"open","publication_status":"draft","verification_status":"unreviewed","tags":["schilderkunst","landschap","kunstenaarskolonie"],"photos":[{"url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/f/fe/Noord-Veluws_Museum_Nunspeet_P1370973.jpg/1280px-Noord-Veluws_Museum_Nunspeet_P1370973.jpg","caption":"Noord-Veluws Museum Nunspeet — Noord-Veluws Museum Nunspeet P1370973","credit":"G.Lanting","source_url":"https://commons.wikimedia.org/wiki/File:Noord-Veluws_Museum_Nunspeet_P1370973.jpg","license":"CC BY 4.0"}],"is_art_museum":true},{"id":"420d6c54-d5ca-5dce-81a2-5e10da22075e","inventory_key":"art-audit:124","name":"Sint Hubertus Kunstcentrum","city":"Genhout","province":"Limburg","street_address":"Hubertusstraat 59","postal_code":"6191 PB","country":"NL","website_url":"https://www.alpedugenhout.nl/","latitude":null,"longitude":null,"summary":"Ontdek Limburgse kunstenaars in een kerk van Alphons Boosten. Kunstwerken en religieuze voorwerpen brengen verschillende vormen van vakmanschap samen. De architectuur maakt deel uit van de ontmoeting met onder anderen Charles Eyck en Joep Nicolas.","operating_status":"open","publication_status":"draft","verification_status":"unreviewed","tags":["religieuze kunst","beeldhouwkunst","glaskunst"],"photos":[{"url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/2/28/Exterieur_OVERZICHT_VOOR-_RECHTERZIJKANT_-_Groot_Genhout_-_20268801_-_RCE.jpg/1280px-Exterieur_OVERZICHT_VOOR-_RECHTERZIJKANT_-_Groot_Genhout_-_20268801_-_RCE.jpg","caption":"Sint Hubertus Kunstcentrum — Exterieur OVERZICHT VOOR- RECHTERZIJKANT - Groot Genhout - 20268801 - RCE","credit":"Paul van Galen","source_url":"https://commons.wikimedia.org/wiki/File:Exterieur_OVERZICHT_VOOR-_RECHTERZIJKANT_-_Groot_Genhout_-_20268801_-_RCE.jpg","license":"CC BY-SA 4.0"}],"is_art_museum":true},{"id":"c576230f-abaa-54b0-b98b-214cf3013e6b","inventory_key":"museum-nl:km21","name":"KM21","city":"Den Haag","province":"Zuid-Holland","street_address":"Stadhouderslaan 43","postal_code":"2517 HV","country":"NL","website_url":"https://www.gem-online.nl/","latitude":52.089202,"longitude":4.279849,"summary":"Ontmoet kunstenaars die midden in het heden staan. KM21 presenteert wisselende tentoonstellingen met uiteenlopende disciplines, van schilderkunst tot video en ruimtelijk werk. Iedere presentatie opent een nieuwe blik op actuele beeldende kunst.","operating_status":"open","publication_status":"draft","verification_status":"unreviewed","tags":["hedendaagse kunst","kunsthal","installaties"],"photos":[{"url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/c/c1/20080906-07_Den_Haag_%280091%29.jpg/1280px-20080906-07_Den_Haag_%280091%29.jpg","caption":"KM21 — 20080906-07 Den Haag (0091)","credit":"Donar Reiskoffer","source_url":"https://commons.wikimedia.org/wiki/File:20080906-07_Den_Haag_(0091).jpg","license":"CC BY 3.0"}],"is_art_museum":true},{"id":"bf46e13a-9d9d-5716-a831-2d0f68f8a9d2","inventory_key":"museum-nl:keramiekcentrum-tiendschuur-tegelen","name":"Keramiekmuseum Tiendschuur","city":"Tegelen","province":"Limburg","street_address":"Kasteellaan 8","postal_code":"5932 AG","country":"NL","website_url":"https://tiendschuur.net/","latitude":51.33162,"longitude":6.136467,"summary":"Ontdek wat klei kan worden. De Tiendschuur verbindt de keramiekgeschiedenis van Tegelen met hedendaagse makers. Historische objecten en wisselende tentoonstellingen laten zien hoe techniek en verbeelding steeds nieuwe vormen opleveren.","operating_status":"open","publication_status":"draft","verification_status":"unreviewed","tags":["keramiek","toegepaste kunst","hedendaagse kunst"],"photos":[{"url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/5/56/Ceramics_Centre_Tiendschuur_Tegelen.jpg/1280px-Ceramics_Centre_Tiendschuur_Tegelen.jpg","caption":"Keramiekmuseum Tiendschuur — Ceramics Centre Tiendschuur Tegelen","credit":"Sindala","source_url":"https://commons.wikimedia.org/wiki/File:Ceramics_Centre_Tiendschuur_Tegelen.jpg","license":"CC BY 4.0"}],"is_art_museum":true},{"id":"581d059e-55d2-5d21-a87c-75e97c51cf00","inventory_key":"art-audit:127","name":"FENIX","city":"Rotterdam","province":"Zuid-Holland","street_address":"Paul Nijghkade 5","postal_code":"3072 AT","country":"NL","website_url":"https://www.fenix.nl/","latitude":null,"longitude":null,"summary":"Kunst geeft persoonlijke gezichten aan migratie in FENIX. Ontdek hoe kunstenaars verhalen van vertrek, aankomst en verbondenheid verbeelden. De historische havenloods vormt een betekenisvolle omgeving voor ontmoetingen met ervaringen van over de hele wereld.","operating_status":"open","publication_status":"draft","verification_status":"unreviewed","tags":["hedendaagse kunst","fotografie","migratie"],"photos":[{"url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/c/cf/Rails_op_Nico_Koomanskade_en_Fenix_II_loods%2C_Katendrecht_Rotterdam.jpg/1280px-Rails_op_Nico_Koomanskade_en_Fenix_II_loods%2C_Katendrecht_Rotterdam.jpg","caption":"FENIX — Rails op Nico Koomanskade en Fenix II loods, Katendrecht Rotterdam","credit":"Joris","source_url":"https://commons.wikimedia.org/wiki/File:Rails_op_Nico_Koomanskade_en_Fenix_II_loods,_Katendrecht_Rotterdam.jpg","license":"CC BY-SA 4.0"}],"is_art_museum":true},{"id":"c80464ad-d921-592b-ae1b-bdd2b8de0833","inventory_key":"museum-nl:mij-museum-ijsselstein","name":"Museum IJsselstein","city":"IJsselstein","province":"Utrecht","street_address":"Walkade 2-4","postal_code":"3401 DS","country":"NL","website_url":"https://www.museumijsselstein.nl/","latitude":52.02034,"longitude":5.0471,"summary":"Laat kunstenaars je meenemen naar actuele vragen. Museum IJsselstein presenteert hedendaagse kunst vanuit verschillende perspectieven en verbindt die met de wereld om ons heen. De tentoonstellingen nodigen uit tot verwondering én gesprek.","operating_status":"open","publication_status":"draft","verification_status":"unreviewed","tags":["hedendaagse kunst","kunsthal"],"photos":[{"url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/a/a6/IJsselstein_Walkade_15-17.jpg/1280px-IJsselstein_Walkade_15-17.jpg","caption":"Museum IJsselstein — IJsselstein Walkade 15-17","credit":"Ikopdefiets","source_url":"https://commons.wikimedia.org/wiki/File:IJsselstein_Walkade_15-17.jpg","license":"CC0"}],"is_art_museum":true},{"id":"94c9f145-8ff6-5ff4-9bd8-1b767ccad566","inventory_key":"museum-nl:ikonenmuseum-kampen","name":"Ikonenmuseum Kampen","city":"Kampen","province":"Overijssel","street_address":"Buiten Nieuwstraat 2","postal_code":"8261 AV","country":"NL","website_url":"https://ikonenmuseumkampen.nl/","latitude":52.558667,"longitude":5.91527,"summary":"Ontdek de verstilde beeldtaal van iconen. Het Ikonenmuseum laat zien hoe kleur, gebaar en symboliek betekenis dragen. Wisselende presentaties verdiepen de kennismaking met deze schilderkunst en haar plaats in het dagelijks geloof.","operating_status":"open","publication_status":"draft","verification_status":"unreviewed","tags":["iconen","religieuze kunst","schilderkunst"],"photos":[{"url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/9/93/Ikonenmuseum_Kampen.jpg/1280px-Ikonenmuseum_Kampen.jpg","caption":"Ikonenmuseum Kampen — Ikonenmuseum Kampen","credit":"Marion Golsteijn","source_url":"https://commons.wikimedia.org/wiki/File:Ikonenmuseum_Kampen.jpg","license":"CC BY-SA 4.0"}],"is_art_museum":true},{"id":"f464bfae-6478-5717-b2c6-b412ef103ba3","inventory_key":"museum-nl:museum-de-wieger","name":"De Wieger Deurne","city":"Deurne","province":"Noord-Brabant","street_address":"Oude Liesselseweg 29","postal_code":"5751 WN","country":"NL","website_url":"https://www.dewieger.nl/","latitude":51.458946,"longitude":5.79607,"summary":"Bezoek het voormalige huis en atelier van Hendrik Wiegersma. Zijn werk ontmoet kunst uit de eerste helft van de twintigste eeuw. Wisselende tentoonstellingen brengen ook hedendaagse makers naar deze persoonlijke plek in Deurne.","operating_status":"open","publication_status":"draft","verification_status":"unreviewed","tags":["moderne kunst","schilderkunst","kunstenaarsmuseum"],"photos":[{"url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/6/60/De_Wieger_Deurne_%28Q3483633%29_-_2.jpg/1280px-De_Wieger_Deurne_%28Q3483633%29_-_2.jpg","caption":"De Wieger Deurne — De Wieger Deurne (Q3483633) - 2","credit":"Hay Kranen","source_url":"https://commons.wikimedia.org/wiki/File:De_Wieger_Deurne_(Q3483633)_-_2.jpg","license":"CC BY 4.0"}],"is_art_museum":true},{"id":"fa78ea52-fba1-58c8-be25-bcecbf33cc78","inventory_key":"art-audit:132","name":"het MAG museum","city":"Ruurlo","province":"Gelderland","street_address":"Borculoseweg 2","postal_code":"7261 BJ","country":"NL","website_url":"https://www.hetmagmuseum.nl/","latitude":null,"longitude":null,"summary":"Ontdek Maastrichts aardewerk en glas met oog voor ontwerp. Het MAG laat zien hoe kunstenaars vorm gaven aan gebruiksvoorwerpen en sierobjecten. Vooral ontwerpen uit de twintigste eeuw maken deze verzameling kleurrijk en verrassend.","operating_status":"open","publication_status":"draft","verification_status":"unreviewed","tags":["keramiek","glaskunst","art deco"],"photos":[],"is_art_museum":true},{"id":"7