m_Jan_van_der_Togt._Amstelveen_001.JPG","caption":"Museum JAN — Museum Jan van der Togt. Amstelveen 001","credit":"Georges Jansoone ( JoJan )","source_url":"https://commons.wikimedia.org/wiki/File:Museum_Jan_van_der_Togt._Amstelveen_001.JPG","license":"CC BY 3.0"}],"is_art_museum":true},{"id":"e35be3e5-0fcc-5a86-99d1-e0e0214ae034","inventory_key":"museum-nl:stadskasteel-zaltbommel","name":"Museum Stadskasteel Zaltbommel","city":"Zaltbommel","province":"Gelderland","street_address":"Nonnenstraat 5","postal_code":"5301 BE","country":"NL","website_url":"https://stadskasteelzaltbommel.nl/","latitude":51.811299,"longitude":5.248997,"summary":"Ontdek de verbeelding van Fiep Westendorp in het Stadskasteel. Haar illustraties ontmoeten schilderijen, meubels en toegepaste kunst. Naast de geschiedenis van Zaltbommel is dit een plek voor liefhebbers van getekende verhalen.","operating_status":"open","publication_status":"draft","verification_status":"unreviewed","tags":["illustratie","toegepaste kunst","Fiep Westendorp"],"photos":[{"url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/0/07/2010-7_mon_13_def%3B_Nonnenstraat_3%3B_nr._40237.jpg/1280px-2010-7_mon_13_def%3B_Nonnenstraat_3%3B_nr._40237.jpg","caption":"Museum Stadskasteel Zaltbommel — 2010-7 mon 13 def; Nonnenstraat 3; nr. 40237","credit":"Claesz","source_url":"https://commons.wikimedia.org/wiki/File:2010-7_mon_13_def;_Nonnenstraat_3;_nr._40237.jpg","license":"CC BY-SA 3.0 nl"}],"is_art_museum":true},{"id":"e8015868-3712-5250-8bc7-c7ddee1f1f42","inventory_key":"museum-nl:nederlands-steendrukmuseum","name":"Nederlands Steendrukmuseum","city":"Valkenswaard","province":"Noord-Brabant","street_address":"Oranje Nassaustraat 8c","postal_code":"5554 AG","country":"NL","website_url":"https://www.steendrukmuseum.nl/","latitude":51.35432,"longitude":5.459051,"summary":"Ontdek hoe een tekening op steen een wereld aan beelden kon verspreiden. Het Steendrukmuseum toont lithografie, drukwerk en het bijbehorende maakproces. Kunst, affiches en techniek laten je anders kijken naar gedrukte beelden.","operating_status":"open","publication_status":"draft","verification_status":"unreviewed","tags":["grafiek","lithografie","illustratie"],"photos":[{"url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/b/bf/Exterieur_Nederlands_Steendrukmuseum.jpg/1280px-Exterieur_Nederlands_Steendrukmuseum.jpg","caption":"Nederlands Steendrukmuseum — Exterieur Nederlands Steendrukmuseum","credit":"FFVO","source_url":"https://commons.wikimedia.org/wiki/File:Exterieur_Nederlands_Steendrukmuseum.jpg","license":"CC BY-SA 4.0"}],"is_art_museum":true},{"id":"d7cfa691-5a5a-5112-b8c0-bae8b65e100f","inventory_key":"museum-nl:nederlands-zilvermuseum","name":"Nederlands Zilvermuseum Schoonhoven","city":"Schoonhoven","province":"Zuid-Holland","street_address":"Kazerneplein 4","postal_code":"2871 CZ","country":"NL","website_url":"https://zilvermuseum.com/","latitude":51.947165,"longitude":4.852309,"summary":"Zie hoe zilver verandert van grondstof in verfijnd ontwerp. Historische en hedendaagse objecten tonen de mogelijkheden van het edelsmeden. Ontdek details, technieken en ideeën achter voorwerpen die tegelijk bruikbaar en bijzonder zijn.","operating_status":"open","publication_status":"draft","verification_status":"unreviewed","tags":["zilver","sieraden","toegepaste kunst"],"photos":[{"url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/9/99/Nederlands_Zilvermuseum_in_Schoonhoven%2C_04-2024.jpg/1280px-Nederlands_Zilvermuseum_in_Schoonhoven%2C_04-2024.jpg","caption":"Nederlands Zilvermuseum Schoonhoven — Nederlands Zilvermuseum in Schoonhoven, 04-2024","credit":"Arian van der Pijl","source_url":"https://commons.wikimedia.org/wiki/File:Nederlands_Zilvermuseum_in_Schoonhoven,_04-2024.jpg","license":"CC BY 4.0"}],"is_art_museum":true},{"id":"3c7d430e-34ed-50f7-b61c-d879c363892b","inventory_key":"museum-nl:nederlands-tegelmuseum","name":"Nederlands Tegelmuseum","city":"Otterlo","province":"Gelderland","street_address":"Eikenzoom 12","postal_code":"6731 BH","country":"NL","website_url":"https://www.nederlandstegelmuseum.nl/","latitude":52.098511,"longitude":5.772575,"summary":"Een tegel kan een heel verhaal vertellen. Ontdek beschilderde tegels en grote tableaus, van historische voorstellingen tot naoorlogse kunst. Het museum laat zien hoe ontwerp en keramische techniek door de eeuwen heen samenkwamen.","operating_status":"open","publication_status":"draft","verification_status":"unreviewed","tags":["keramiek","tegelkunst","toegepaste kunst"],"photos":[{"url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/3/3c/Nederlands_Tegelmuseum.jpg/1280px-Nederlands_Tegelmuseum.jpg","caption":"Nederlands Tegelmuseum — Nederlands Tegelmuseum","credit":"Rasbak","source_url":"https://commons.wikimedia.org/wiki/File:Nederlands_Tegelmuseum.jpg","license":"CC BY-SA 3.0"}],"is_art_museum":true},{"id":"8a861a3c-e5e5-5488-a90a-36903b5154c5","inventory_key":"wikipedia:Drenthe:vangoghhuis:nieuwamsterdam","name":"Van Gogh Huis Drenthe","city":"Veenoord","province":"Drenthe","street_address":"Van Goghstraat 1","postal_code":"7844 NP","country":"NL","website_url":"https://vangogh-drenthe.nl/","latitude":null,"longitude":null,"summary":"Volg Van Gogh tijdens zijn Drentse maanden. In het voormalige logement ontdek je zijn zoektocht als schilder en zijn blik op het landschap. De ingerichte kamer maakt zijn verblijf tastbaar, zonder originele werken te suggereren.","operating_status":"open","publication_status":"draft","verification_status":"unreviewed","tags":["kunstenaarsmuseum","Vincent van Gogh"],"photos":[{"url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/a/ad/Netherlands_Emmen_Nieuw-Amsterdam_Van_Gogh_Huis.JPG/1280px-Netherlands_Emmen_Nieuw-Amsterdam_Van_Gogh_Huis.JPG","caption":"Van Gogh Huis Drenthe — Netherlands Emmen Nieuw-Amsterdam Van Gogh Huis","credit":"Onderwijsgek","source_url":"https://commons.wikimedia.org/wiki/File:Netherlands_Emmen_Nieuw-Amsterdam_Van_Gogh_Huis.JPG","license":"CC BY-SA 2.5 nl"}],"is_art_museum":true},{"id":"ef7609e1-fc69-5d14-9786-0a5070c2a13b","inventory_key":"wikipedia:Groningen:museummhlmann:appingedam","name":"Museum Møhlmann","city":"Appingedam","province":"Groningen","street_address":"Westersingel 104","postal_code":"9901 GK","country":"NL","website_url":"https://www.museummohlmann.nl/","latitude":null,"longitude":null,"summary":"Ontdek hedendaagse realistische en figuratieve kunst met aandacht voor ambacht en waarneming. Museum Møhlmann brengt verschillende Nederlandse kunstenaars samen. Zorgvuldig geschilderde details nodigen uit om langer te blijven kijken.","operating_status":"open","publication_status":"draft","verification_status":"unreviewed","tags":["realisme","figuratieve kunst","schilderkunst"],"photos":[{"url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/8/86/Entree_Museum_M%C3%B8hlmann_te_Appingedam-1498210961.jpg/1280px-Entree_Museum_M%C3%B8hlmann_te_Appingedam-1498210961.jpg","caption":"Museum Møhlmann — Entree Museum Møhlmann te Appingedam-1498210961","credit":"Rob Møhlmann","source_url":"https://commons.wikimedia.org/wiki/File:Entree_Museum_M%C3%B8hlmann_te_Appingedam-1498210961.jpg","license":"CC BY-SA 4.0"}],"is_art_museum":true},{"id":"a6452694-a45d-58d8-8628-5de0e30bdc9d","inventory_key":"museum-nl:de-nieuwe-kerk","name":"De Nieuwe Kerk Amsterdam","city":"Amsterdam","province":"Noord-Holland","street_address":"Dam 12","postal_code":"1012 NP","country":"NL","website_url":"https://www.nieuwekerk.nl/en/","latitude":52.37399,"longitude":4.891708,"summary":"Laat je verrassen door wisselende kunst- en fotografietentoonstellingen in De Nieuwe Kerk. De monumentale ruimte geeft iedere presentatie een eigen sfeer. Het programma verandert; bekijk vooraf welke tentoonstelling er te zien is.","operating_status":"open","publication_status":"draft","verification_status":"unreviewed","tags":["kunsthal","fotografie","oude kunst"],"photos":[{"url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/a/ab/Nieuwe_Kerk%2C_Amsterdam.JPG/1280px-Nieuwe_Kerk%2C_Amsterdam.JPG","caption":"De Nieuwe Kerk Amsterdam — Nieuwe Kerk, Amsterdam","credit":"Pemolo","source_url":"https://commons.wikimedia.org/wiki/File:Nieuwe_Kerk,_Amsterdam.JPG","license":"CC BY-SA 3.0 nl"}],"is_art_museum":true},{"id":"6f61c002-72c5-5220-8ccf-5108ab3847e4","inventory_key":"art-audit:148","name":"Museum No Hero","city":"Delden","province":"Overijssel","street_address":"Hengelosestraat 2/4","postal_code":"7491 BR","country":"NL","website_url":"https://www.museumnohero.nl/","latitude":null,"longitude":null,"summary":"Museum No Hero is gesloten. De voormalige locatie in de Oude Rentmeesterij heeft een nieuwe museale bestemming als Museum MORE Twickel. Die instelling is afzonderlijk opgenomen in Kunstkiezer.","operating_status":"closed","publication_status":"draft","verification_status":"unreviewed","tags":["schilderkunst","beeldhouwkunst","toegepaste kunst"],"photos":[{"url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/f/fd/Ingang_museum_No_Hero.jpg/1280px-Ingang_museum_No_Hero.jpg","caption":"Museum No Hero — Ingang museum No Hero","credit":"Mx Lucy","source_url":"https://commons.wikimedia.org/wiki/File:Ingang_museum_No_Hero.jpg","license":"CC BY-SA 4.0"}],"is_art_museum":true},{"id":"69be9209-e151-5ee7-929d-f4c76f560787","inventory_key":"art-audit:149","name":"Cultuurhuis Bergeijk","city":"Bergeijk","province":"Noord-Brabant","street_address":"Domineestraat 8a","postal_code":"5571 EJ","country":"NL","website_url":"https://cultuurhuisbergeijk.nl/","latitude":null,"longitude":null,"summary":"Ontdek de vernieuwende ontwerpgeschiedenis van Bergeijk. Textiel, architectuur en wisselende exposities laten zien hoe makers het dorp een eigen karakter gaven. De tuin en rondleidingen verbinden de ideeën met de omgeving.","operating_status":"open","publication_status":"draft","verification_status":"unreviewed","tags":["design","architectuur","textiel"],"photos":[],"is_art_museum":true},{"id":"878fe3f1-3c25-5be4-9dc7-76ffb629ad0a","inventory_key":"wikipedia:Limburg:museumvaals:vaals","name":"Museum Vaals","city":"Vaals","province":"Limburg","street_address":"Eschberg 7","postal_code":"6291 NK","country":"NL","website_url":"https://museumvaals.nl/","latitude":null,"longitude":null,"summary":"Ontmoet een verzameling grote heiligenbeelden in een voormalige kloosterkapel. Museum Vaals combineert deze expressieve figuren met wisselende hedendaagse kunst. De ontmoeting tussen oude devotie en nieuwe beelden maakt nieuwsgierig.","operating_status":"temporarily_closed","publication_status":"draft","verification_status":"unreviewed","tags":["beeldhouwkunst","religieuze kunst","hedendaagse kunst"],"photos":[{"url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/d/da/Vaals-Eschberg_7_%281%29.JPG/1280px-Vaals-Eschberg_7_%281%29.JPG","caption":"Museum Vaals — Vaals-Eschberg 7 (1)","credit":"Romaine","source_url":"https://commons.wikimedia.org/wiki/File:Vaals-Eschberg_7_(1).JPG","license":"CC0"}],"is_art_museum":true},{"id":"712b6a6e-d1c5-52e2-b8cb-9ee8c41eb0e2","inventory_key":"museum-nl:kunstinstituut-melly","name":"Kunstinstituut Melly","city":"Rotterdam","province":"Zuid-Holland","street_address":"Witte De Withstraat 50","postal_code":"3012 BR","country":"NL","website_url":"https://www.kunstinstituutmelly.nl","latitude":51.915469,"longitude":4.477051,"summary":"Ontdek internationale kunstenaars en actuele ideeën bij Kunstinstituut Melly. Tentoonstellingen en publieksprogramma''s onderzoeken de relatie tussen kunst en samenleving. De instelling biedt ruimte aan nieuwe stemmen en onverwachte ontmoetingen.","operating_status":"open","publication_status":"draft","verification_status":"unreviewed","tags":["hedendaagse kunst","kunsthal","installaties"],"photos":[{"url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/2/25/Witte_de_With_Center_for_Contemporary_Art.TIF/lossy-page1-1280px-Witte_de_With_Center_for_Contemporary_Art.TIF.jpg","caption":"Kunstinstituut Melly — Witte de With Center for Contemporary Art","credit":"Bob Goedewaagen","source_url":"https://commons.wikimedia.org/wiki/File:Witte_de_With_Center_for_Contemporary_Art.TIF","license":"CC BY 3.0"}],"is_art_museum":true},{"id":"6680fea1-fc3d-59b8-8ce7-193a2fbf7d29","inventory_key":"art-audit:156","name":"Kunsthuis Waterland","city":"Purmerend","province":"Noord-Holland","street_address":"Peperstraat 36","postal_code":"","country":"NL","website_url":"https://kunsthuiswaterland.nl/","latitude":null,"longitude":null,"summary":"Ontdek wisselende tentoonstellingen bij Kunsthuis Waterland. Kunstenaars met verschillende werkwijzen krijgen hier een podium. De combinatie van expositieruimte en kunstuitleen brengt hedendaagse kunst dichtbij het dagelijks leven.","operating_status":"open","publication_status":"draft","verification_status":"unreviewed","tags":["hedendaagse kunst","kunsthal"],"photos":[],"is_art_museum":true},{"id":"f7f0e959-1239-54f5-93a6-825a57eeba00","inventory_key":"wikipedia:Zuid-Holland:museumofcomicart:noordwijk","name":"Museum of Comic Art","city":"Noordwijk","province":"Zuid-Holland","street_address":"Bomstraat 11","postal_code":"2202 GH","country":"NL","website_url":"https://www.museumofcomicart.nl/","latitude":null,"longitude":null,"summary":"Bekijk strips vanaf de tekentafel. Originele tekeningen laten zien hoe lijnen, kaders en personages samen een verhaal worden. Het Museum of Comic Art geeft de negende kunst ruimte voor aandachtig kijken.","operating_status":"open","publication_status":"draft","verification_status":"unreviewed","tags":["stripkunst","illustratie","tekenkunst"],"photos":[{"url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/1/18/Noordwijk_-_Museum_of_Comic_Art_%28MoCA%29_20210829.jpg/1280px-Noordwijk_-_Museum_of_Comic_Art_%28MoCA%29_20210829.jpg","caption":"Museum of Comic Art — Noordwijk - Museum of Comic Art (MoCA) 20210829","credit":"Otter","source_url":"https://commons.wikimedia.org/wiki/File:Noordwijk_-_Museum_of_Comic_Art_(MoCA)_20210829.jpg","license":"CC BY-SA 4.0"}],"is_art_museum":true},{"id":"3581b76b-ca42-5922-9a05-808e98a31588","inventory_key":"museum-nl:museum-van-de-geest-amsterdam","name":"Museum van de geest | Outsider Art","city":"Amsterdam","province":"Noord-Holland","street_address":"Amstel 51","postal_code":"1018 EJ","country":"NL","website_url":"https://www.museumvandegeest.nl","latitude":52.364814,"longitude":4.902185,"summary":"Museum van de Geest verzamelt outsider art: beeldende kunst buiten de gangbare routes. De voormalige Amsterdamse vermelding vraagt controle, omdat de actuele website Haarlemse locaties toont. Controleer de bezoeklocatie voordat je deze vermelding publiceert.","operating_status":"unknown","publication_status":"draft","verification_status":"unreviewed","tags":["outsider art","hedendaagse kunst"],"photos":[],"is_art_museum":true}]'::jsonb)
 on conflict(id) do update set inventory_key=excluded.inventory_key,name=excluded.name,city=excluded.city,province=excluded.province,street_address=excluded.street_address,postal_code=excluded.postal_code,country=excluded.country,website_url=excluded.website_url,latitude=excluded.latitude,longitude=excluded.longitude,summary=excluded.summary,operating_status=excluded.operating_status,publication_status=excluded.publication_status,verification_status=excluded.verification_status,tags=excluded.tags,photos=excluded.photos,is_art_museum=excluded.is_art_museum
 where not m.is_art_museum and m.publication_status='draft'
 and not exists(select 1 from kunstkiezer_private.museum_changes c where c.museum_id=m.id and c.editor_id is not null)
 returning id
) insert into kk_art_changed select id from changed;
